// every core's flows cover its placed bytes (rounded up to the granule); every bank's total is within one granule of 1/8
constexpr bool plan_ok() {
    for (uint32_t h = 0; h < kHarvests; ++h)
        for (uint32_t f = 0; f < kFrames; ++f) {
            uint64_t bank[kBanks] = {}, tot = 0;
            for (uint32_t c = 0; c < kCores; ++c) {
                const CoreFlows& x = kPlan[h][f][c];
                uint64_t s = 0;
                for (uint32_t k = 0; k < x.n; ++k) { s += x.f[k].bytes; bank[x.f[k].bank] += x.f[k].bytes; if (x.f[k].bank >= kBanks || x.f[k].endpoint >= 3) return false; }
                if (s < x.placed_bytes || s >= uint64_t(x.placed_bytes) + kGranule) { if (!(x.placed_bytes == 0 && s == 0)) return false; }
                tot += s;
            }
            for (uint32_t b = 0; b < kBanks; ++b) if (bank[b] * kBanks + kBanks * kGranule < tot || bank[b] * kBanks > tot + kBanks * kGranule) return false;
        }
    return true;
}
static_assert(plan_ok(), "dram_plan: a core's flows do not cover its weights, or the banks are not even");

